function swapAdjectives(sentence) {
  const words = sentence.split(' '); // Split the sentence into an array of words
  let i = -1;
  let j = -1;
  for (let k = 0; k < words.length; k++) {
    if (isAdjective(words[k]) && i === -1) {
      i = k;
    }
    if (isAdjective(words[k]) && j !== -1) {
      [words[i], words[j]] = [words[j], words[i]];
      break;
    }
    if (isAdjective(words[k]) && k > j) {
      j = k;
    }
  }
  return words.join(' ') + '.'; // Rejoin the modified array into a string and add a period at the end
}

