```typescript
@Injectable()
export class LoggerMiddleware implements NestMiddleware {
  // The @Injectable() decorator marks this class as a provider that can be injected in other parts of the application

  use(req: Request, res: Response, next: NextFunction) {
    // The use method is called when the middleware is applied to a route or an HTTP request

    const logMessage = `${new Date()} ${req.method} ${req.originalUrl}\n`;
    // Creating a log message with the current date, HTTP method, and original URL of the request

    fs.appendFile('./log.txt', logMessage, (err) => {
      if (err) throw err;
      // Using the fs (file system) module to append the log message to the 'log.txt' file

      next();
      // Calling next() function passes control to the next middleware or the final handler
    });
  }
}
```

