```csharp
using System;
using System.Net.Http;
using System.Text;
using Newtonsoft.Json;

public class RestServiceWrapper<T>
{
    private readonly string _baseUrl;
    private readonly HttpClient _httpClient;
    private string _accessToken;

    public RestServiceWrapper(string baseUrl)
    {
        _baseUrl = baseUrl;
        _httpClient = new HttpClient();
    }

    public void SetAccessToken(string accessToken)
    {
        _accessToken = accessToken;
        _httpClient.DefaultRequestHeaders.Authorization = new AuthenticationHeaderValue("Bearer", _accessToken);
    }

    public async Task<T> GetAsync(string endpoint)
    {
        using (var response = await _httpClient.GetAsync($"{_baseUrl}/{endpoint}"))
        {
            response.EnsureSuccessStatusCode();
            var content = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<T>(content);
        }
    }

    public async Task<T> PostAsync(string endpoint, T data)
    {
        using var stringTask = JsonConvert.SerializeObject(data);
        using var content = new StringContent(stringTask.Result, Encoding.UTF8, "application/json");

        using (var response = await _httpClient.PostAsync($"{_baseUrl}/{endpoint}", content))
        {
            response.EnsureSuccessStatusCode();
            var contentResponse = await response.Content.ReadAsStringAsync();
            return JsonConvert.DeserializeObject<T>(contentResponse);
        }
    }
}

