function determineProtocol(inputData) {
  // Check if input data matches IPv6 format
  const sourceIPv6Regex = /^([0-9a-f:]{1,4}){7}[0-9a-f:]{1,4}$/i;
  const destinationIPv6Regex = /^([0-9a-f:]{1,4}){7}[0-9a-f:]{1,4}$/i;
  const isSourceIPv6 = sourceIPv6Regex.test(inputData.sourceIP);
  const isDestinationIPv6 = destinationIPv6Regex.test(inputData.destinationIP);

  let protocol = null;

  // If both source and destination IPs are IPv6, check for UDP or HTTP based on port number
  if (isSourceIPv6 && isDestinationIPv6) {
    if (inputData.port === 80) {
      protocol = "HTTP";
    } else {
      protocol = "UDP";
    }
  }
  // If source or destination IP is not IPv6, default to HTTP
  else {
    protocol = "HTTP";
  }

  return protocol;
}
