const axios = require('axios');

async function getAntonyms(word) {
  const url = 'https://api.datamuse.com/words';
  const params = {
    rel_antonym: true,
    max: 5, // Fetch up to 5 results
  };

  try {
    const result = await axios.get(url, { params: { ...params, md5: word } });
    return result.data;
  } catch (error) {
    if (error.response && error.response.status === 404) {
      return [];
    } else {
      throw error;
    }
  }
}

async function main() {
  const word = process.argv[2];

  if (!word) {
    console.log("Usage: node index.js <word>");
    process.exit(1);
  }

  const antonyms = await getAntonyms(word);

  if (antonyms.length > 0) {
    console.log(`Antonyms for "${word}":`);
    antonyms.forEach((antonym) => console.log(`- ${antonym.word}`));
  } else {
    console.log(`No antonyms found for "${word}"`);
  }
}

main();
```

