void generatePermutations(string str, vector<string>& perms) {
    int n = str.length();
    if (n == 0 || n == 1) {
        perms.push_back(str);
        return;
    }
    char c = str[0];
    string rem = str.substr(1);
    vector<string> subperms;
    generatePermutations(rem, subperms);
