 To identify if a given sentence in Go contains a double negative, follow these steps:

1. Create a slice of specific negative words.
2. Split the given sentence into individual words.
3. Iterate through each word in the sentence.
4. Check if the current word is a negative word or the word "not".
5. If the current word is a negative word, remember its index in the sentence.
6. If another negative word or the word "not" is found before the first negative word, then the sentence contains a double negative.

Here's an example Go code snippet implementing this logic:

```go
package main

import (
	"fmt"
	"strings"
)

func main() {
	negativeWords := []string{"isn't", "aren't", "doesn't", "don't", "haven't", "hasn't", "won't", "wouldn't", "can't", "couldn't", "may not", "might not", "must not", "shall not", "should not", "will not"}
	sentence := "He isn't not worried about the coronavirus situation"

	words := strings.Split(sentence, " ")
	for i, word := range words {
		if containsNegativeWord(word) || word == "not" {
			prevWord := ""
			if i > 0 {
				prevWord = words[i-1]
			}
			if containsNegativeWord(prevWord) && word == "not" {
				fmt.Println("The sentence contains a double negative.")
				return
			}
		}
	}
	fmt.Println("The sentence does not contain a double negative.")
}

func containsNegativeWord(word string) bool {
	for _, negativeWord := range negativeWords {
		if strings.EqualFold(negativeWord, word) {
			return true
		}
	}
	return false
}
```

